class ThemeManager{constructor(){this.STORAGE_KEY='portfolio-theme';this.init()}init(){this.setupToggleButton();this.updateButtonState()}getCurrentTheme(){return document.documentElement.getAttribute('data-theme')||'light'}setTheme(theme){document.documentElement.setAttribute('data-theme',theme);localStorage.setItem(this.STORAGE_KEY,theme);this.updateButtonState();this.updatePhoneDisplay()}toggleTheme(){const current=this.getCurrentTheme();const newTheme=current==='light'?'dark':'light';this.setTheme(newTheme)}updateButtonState(){const btn=document.getElementById('theme-toggle');if(btn){btn.textContent=this.getCurrentTheme()==='light'?'🌙':'☀️'}}setupToggleButton(){const btn=document.getElementById('theme-toggle');if(btn){btn.addEventListener('click',()=>this.toggleTheme())}}updatePhoneDisplay(){const timeElement=document.getElementById('phone-time');if(timeElement){const now=new Date();const hours=String(now.getHours()).padStart(2,'0');const minutes=String(now.getMinutes()).padStart(2,'0');timeElement.textContent=`${hours}:${minutes}`}}}class TimeUpdater{constructor(){this.init()}init(){this.updateTime();setInterval(()=>this.updateTime(),60000)}updateTime(){const timeElement=document.getElementById('phone-time');if(timeElement){const now=new Date();const hours=String(now.getHours()).padStart(2,'0');const minutes=String(now.getMinutes()).padStart(2,'0');timeElement.textContent=`${hours}:${minutes}`}const profileTimeElement=document.getElementById('phone-time-profile');if(profileTimeElement){const now=new Date();const hours=String(now.getHours()).padStart(2,'0');const minutes=String(now.getMinutes()).padStart(2,'0');profileTimeElement.textContent=`${hours}:${minutes}`}}}let themeManager;let timeUpdater;if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',function(){themeManager=new ThemeManager();timeUpdater=new TimeUpdater()})}else{themeManager=new ThemeManager();timeUpdater=new TimeUpdater()}
